css:
/* HNS warehouse label CSS, as-is - it is what gives the label its cut.
   The page-width/page-height pair is the one addition: frappe reads the PDF
   page size off .print-format, so without it Get PDF falls back to A4. */
.print-format{
	padding: 0px !important;
	/*margin-bottom: 5px;*/
	/*margin-top:6px;*/
}
table, td {
	height:0px;
	padding:0px !important;
	font-size:10px;
	font-family:calibri;
}
table {
	width:100%;
	padding:0px !important;
	text-align:center;
	border-collapse: collapse;
}
@page {
	margin-top: 1px !important;
	margin-bottom: 1px;
	margin-left: 1px;
	margin-right: 1px;
	/*size: 50mm 25mm;*/
}
.print-format{
	page-width: 76mm;
	page-height: 38mm;
	padding: 0px !important;
	margin-bottom: 0px;
	margin-top:0px !important;
}

@media print {
  @page {
    size: 76mm 38mm;
  }
}
